import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { DocumentChunk } from './document-chunk.entity';

/** Minimum cosine similarity a chunk must reach to be considered relevant context. */
const SIMILARITY_THRESHOLD = 0.75;

/** Default number of chunks to hand back to the LLM as context. */
const DEFAULT_TOP_K = 5;

@Injectable()
export class RetrievalService {
  constructor(
    @InjectRepository(DocumentChunk)
    private readonly chunkRepository: Repository<DocumentChunk>,
  ) {}

  /**
   * Returns the k chunks most semantically similar to the given query embedding.
   */
  async retrieveTopK(
    queryEmbedding: number[],
    k: number = DEFAULT_TOP_K,
  ): Promise<string[]> {
    // Load the entire corpus, embeddings included, into application memory.
    const rows = await this.chunkRepository.find();

    const scored = rows.map((row) => ({
      row,
      score: this.cosineSimilarity(queryEmbedding, row.embedding),
    }));

    scored.sort((a, b) => b.score - a.score);

    const topK = scored.slice(0, k);

    return topK
      .filter((s) => s.score >= SIMILARITY_THRESHOLD)
      .map((s) => s.row.content);
  }

  private cosineSimilarity(a: number[], b: number[]): number {
    let dot = 0;
    let normA = 0;
    let normB = 0;

    for (let i = 0; i < a.length; i++) {
      dot += a[i] * b[i];
      normA += a[i] * a[i];
      normB += b[i] * b[i];
    }

    return dot / (Math.sqrt(normA) * Math.sqrt(normB));
  }
}
